// Công nợ phải trả nhà cung cấp, gom theo đối tác từ các phiếu ghi rõ "chưa thanh toán" —
// hỗ trợ kế toán lên kế hoạch dòng tiền, biết cần trả ai trước.
const d = $json;
const items = d.items || [];
const vnd = n => new Intl.NumberFormat('vi-VN').format(n || 0) + '₫';

const rows = items.map(v => `<tr><td>${v.partner_name}</td><td align="right">${v.count}</td><td align="right"><b>${vnd(v.total_outstanding)}</b></td><td>${new Date(v.oldest_date).toLocaleDateString('vi-VN')}</td></tr>`).join('');

const html = `<h2>💸 Công nợ phải trả — ${items.length} nhà cung cấp</h2>`
  + `<p>Tổng còn phải trả: <b style="color:#c00">${vnd(d.total_outstanding)}</b>.</p>`
  + `<table border="1" cellpadding="6" cellspacing="0" style="border-collapse:collapse">`
  + `<tr><th>Nhà cung cấp</th><th>Số phiếu</th><th>Còn nợ</th><th>Phiếu cũ nhất</th></tr>${rows}</table>`
  + `<p style="color:#888;font-size:12px">${d.company_name} — ${new Date().toLocaleString('vi-VN', { timeZone: 'Asia/Ho_Chi_Minh' })}</p>`;

return { json: {
  email_to: d.company_email || '',
  email_subject: `💸 Công nợ phải trả — ${items.length} NCC, tổng ${vnd(d.total_outstanding)}`,
  email_html: html
} };
